function pixelHeroURI(){
  const W = 72, H = 18, pal = ['#2b43d0', '#f3c700', '#e0352a', '#141414'];
  let rects = '';
  for(let y = 0; y < H; y++) for(let x = 0; x < W; x++){
    const t = x / W, fade = t * 1.12 + (y / H) * 0.12;
    const s = Math.sin(x * 12.9898 + y * 78.233) * 43758.5453; const rnd = s - Math.floor(s);
    if(rnd < 0.92 - fade){
      const band = Math.floor((x + y * 2) / 6 + rnd * 1.6);
      const col = pal[((band % pal.length) + pal.length) % pal.length];
      rects += `<rect x="${x}" y="${y}" width="1" height="1" fill="${col}"/>`;
    }
  }
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" shape-rendering="crispEdges">${rects}</svg>`;
  return 'data:image/svg+xml,' + encodeURIComponent(svg);
}
