        + group('Cards', cds.map(([c]) => row(typeIc(c.t), 'item', c.id, mark(c.n.length > 90 ? c.n.slice(0, 88).trim() + '…' : c.n, w), `<span class="card-chip ${chipCls(c.t)}">${esc(shortType(c.t))}</span>${c.l ? `<span class="sx-lv">${esc(LEVEL[c.l] || c.l)}</span>` : ''}${c.d ? `<span class="sx-dt">${esc(fmtDate(c.d))}</span>` : ''}`, 'card-ic ' + chipCls(c.t))).join(''), all.length ? fmt(all.length) + ' matches' : '');
      if(all.length > cds.length){ items.push({all: v}); const i = items.length - 1; h += `<button type="button" class="sx-all${i === sel ? ' on' : ''}" data-sxi="${i}">See all ${fmt(all.length)} results for “${esc(v)}” <span aria-hidden="true">→</span></button>`; }
